// ----------------------------------------------------------------------------
// Logo de la Corporacion Cinefilia en base64 (para incrustarlo en los PDF con
// jsPDF) y datos de contacto oficiales para el pie de pagina de los reportes.
//   - LOGO_CINEFILIA_BLANCO: para franjas/encabezados de color (fondo oscuro)
//   - LOGO_CINEFILIA_NEGRO:  para fondos blancos
// ============================================================================

export const LOGO_CINEFILIA_BLANCO = 'data:image/png;base64,';

export const LOGO_CINEFILIA_NEGRO = 'data:image/png;base64,';

export const CONTACTO_CINEFILIA = {
  nombre: 'Corporacion Cinefilia',
  ciudad: 'Medellin, Colombia',
  correo: 'info@cinefilia.org.co',
  whatsapp: '+57 311 344 6586',
  web: 'cinefilia.org  -  labguion.com',
  instagram: '@cinefilia_colombia',
};

// Dibuja el pie de contacto de Cinefilia en un documento jsPDF.
export function piePdfCinefilia(doc, yBase, xBase = 14) {
  const c = CONTACTO_CINEFILIA;
  doc.setDrawColor(210, 210, 210);
  doc.line(xBase, yBase - 4, xBase + 182, yBase - 4);
  doc.setFont(undefined, 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(90, 90, 90);
  doc.text(`${c.nombre}  -  ${c.ciudad}`, xBase, yBase);
  doc.setFont(undefined, 'normal');
  doc.setFontSize(8);
  doc.setTextColor(120, 120, 120);
  doc.text(`Correo: ${c.correo}    WhatsApp: ${c.whatsapp}`, xBase, yBase + 4);
  doc.text(`Web: ${c.web}    Instagram: ${c.instagram}`, xBase, yBase + 8);
}
